 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    def separators(lines):
        out = []
        for i, line in enumerate(lines):
            if line and all(v == line[0] for v in line) and line[0] != bg:
                out.append(i)
        return out

    row_seps = set(separators(grid))
    col_seps = set(separators([[grid[r][c] for r in range(h)] for c in range(w)]))

    def spans(n, seps):
        result, start = [], 0
        for i in sorted(seps):
            if start < i:
                result.append((start, i))
            start = i + 1
        if start < n:
            result.append((start, n))
        return result

    rows, cols = spans(h, row_seps), spans(w, col_seps)
    # Use the tile containing the most non-background marks as the motif.
    motif = max(((r0, r1, c0, c1) for r0, r1 in rows for c0, c1 in cols),
                key=lambda b: sum(grid[r][c] != bg for r in range(b[0], b[1]) for c in range(b[2], b[3])))
    r0, r1, c0, c1 = motif
    mh, mw = r1 - r0, c1 - c0
    out = [row[:] for row in grid]
    for a, b in rows:
        for c, d in cols:
            for r in range(a, b):
                for x in range(c, d):
                    out[r][x] = grid[r0 + (r - a) % mh][c0 + (x - c) % mw]
    return out
